import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')
SECRET = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, email TEXT, role TEXT DEFAULT "user")')
    db.execute('CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY, owner_id INTEGER, title TEXT, content TEXT, classification TEXT DEFAULT "internal")')
    db.execute('CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, action TEXT, user_id INTEGER, ts DATETIME DEFAULT CURRENT_TIMESTAMP)')
    db.commit()
    db.close()

def verify_session(token):
    """Verify session token format: user_id:timestamp:signature"""
    if not token:
        return None
    parts = token.split(':')
    if len(parts) != 3:
        return None
    user_id, ts, sig = parts
    expected = hmac.new(SECRET.encode(), f"{user_id}:{ts}".encode(), hashlib.sha256).hexdigest()[:16]
    if hmac.compare_digest(sig, expected):
        return int(user_id)
    return None

@app.route('/api/documents/search')
def search_documents():
    """Search documents by title - supports advanced query syntax"""
    user_id = verify_session(request.headers.get('X-Session-Token'))
    if not user_id:
        return jsonify({'error': 'unauthorized'}), 401

    query = request.args.get('q', '')
    doc_type = request.args.get('type', 'all')

    # Build search query with owner filter
    base_query = "SELECT id, title, classification FROM documents WHERE owner_id = " + str(user_id)

    if query:
        # Apply search filter
        base_query += " AND title LIKE '%" + query + "%'"

    if doc_type != 'all':
        base_query += " AND classification = '" + doc_type + "'"

    db = get_db()
    try:
        results = db.execute(base_query).fetchall()
        return jsonify({'documents': [dict(r) for r in results]})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'search failed'}), 500

@app.route('/api/documents/<int:doc_id>')
def get_document(doc_id):
    user_id = verify_session(request.headers.get('X-Session-Token'))
    if not user_id:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ? AND owner_id = ?', (doc_id, user_id)).fetchone()
    if not doc:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(doc))

@app.route('/api/documents', methods=['POST'])
def create_document():
    user_id = verify_session(request.headers.get('X-Session-Token'))
    if not user_id:
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    title = data.get('title', 'Untitled')
    content = data.get('content', '')

    db = get_db()
    db.execute('INSERT INTO documents (owner_id, title, content) VALUES (?, ?, ?)', (user_id, title, content))
    db.execute('INSERT INTO audit_log (action, user_id) VALUES (?, ?)', ('create_doc', user_id))
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
